# What the list is: the line clicked, the asset and the range (in the device's time zone)
from java.text import SimpleDateFormat
from java.util import TimeZone
p = value['params'] or {}
def fmt(d):
	if d is None: return ''
	f = SimpleDateFormat('MMM d, HH:mm')
	if value['tz']: f.setTimeZone(TimeZone.getTimeZone(value['tz']))
	return f.format(d)
return u'%s%s \u00b7 %s to %s' % (p.get('assetName') or '', (u' \u00b7 %s' % p['label']) if p.get('label') else '', fmt(p.get('startDate')), fmt(p.get('endDate')))
